
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_hjs_pbe_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_hjs_pbe", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.307284892851853e+00, -3.244957502748627e+00, -3.157670551820292e+00, -3.036860307406926e+00, -2.872464126089835e+00, -2.654148181106252e+00, -2.374197986626278e+00, -2.032696461563771e+00, -1.644203974933391e+00, -1.238545850984658e+00, -8.419430396396359e-01, -5.850253549006503e-01, -5.126335246961630e-01, -4.229869838299856e-01, -3.088856088558593e-01, -2.009096195980556e-01, -1.145356520994636e-01, -4.739645183089482e-02, -1.080251440287438e-02, -1.204891687907546e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


